<script lang="ts">import {enhance} from '$app/forms';import AppHeader from '$lib/AppHeader.svelte';import {LockKeyhole,ArrowRight,LoaderCircle} from 'lucide-svelte';import type {PageProps} from './$types';let {form}:PageProps=$props();let pending=$state(false);</script>
<svelte:head><title>Choose a new password — Rose Atelier</title><meta name="robots" content="noindex"/></svelte:head>
<div class="app-shell"><AppHeader/><main class="password-main"><section class="auth-card"><span class="auth-flower"><LockKeyhole size={25}/></span><span class="eyebrow">A FRESH START</span><h1>A new password,<br/><i>a little peace of mind.</i></h1><p class="auth-intro">Choose a new password to keep your little lookbook yours.</p>{#if form?.message}<div class="auth-message error" role="alert">{form.message}</div>{/if}<form class="email-form" method="POST" use:enhance={()=>{pending=true;return async({update})=>{try{await update({reset:true});}finally{pending=false;}};}}><label for="new-password">New password</label><div class="auth-input"><LockKeyhole size={17}/><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required disabled={pending}/></div><label for="confirmation">Confirm your password</label><div class="auth-input"><LockKeyhole size={17}/><input id="confirmation" name="confirmation" type="password" autocomplete="new-password" minlength="8" maxlength="128" required disabled={pending}/></div><button class="primary auth-submit" disabled={pending}>{#if pending}<LoaderCircle size={18} class="spin"/>Saving…{:else}Save my new password<ArrowRight size={17}/>{/if}</button></form></section></main></div>
